from pathlib import Path
import py_compile, shutil, sys
p=Path(sys.argv[1] if len(sys.argv)>1 else "app.py")
backup=p.with_name(p.name+".before_admin_entries_v24.bak")
marker="# ==================== ADMIN ENTRIES FULL EDIT V24 ===================="
if not p.is_file(): raise SystemExit(f"Missing {p}")
s=p.read_text(encoding="utf-8")
if marker in s:
 print("Admin Entries V24 already installed.");raise SystemExit(0)
patch='\n\n# ==================== ADMIN ENTRIES FULL EDIT V24 ====================\n# /entries-v14 is the central administrator editor for Timer records.\n# Draft invoice lines linked to an edited Timer are synchronized; issued invoices remain historical.\n\ndef _v24_float(value, default=0.0):\n    try:\n        return float(value)\n    except (TypeError, ValueError):\n        return default\n\n\ndef _v24_entry_snapshot(t):\n    return {\n        \'id\': t.id,\n        \'user_id\': t.user_id,\n        \'client_id\': t.client_id,\n        \'matter_id\': t.matter_id,\n        \'service_date\': t.start_time.date().isoformat() if t.start_time else None,\n        \'services\': t.services,\n        \'notes\': t.notes,\n        \'worked_hours\': float(t.worked_hours or 0),\n        \'billable_hours\': float(t.billable_hours or 0),\n        \'applied_rate\': float(t.applied_rate or 0),\n        \'billable\': bool(t.billable),\n        \'amount\': float(t.amount or 0),\n        \'invoiced_status\': t.invoiced_status,\n        \'invoice_number\': t.invoice_number,\n    }\n\n\nADMIN_ENTRIES_V24 = r\'\'\'{% extends "base.html" %}{% block content %}\n<h1>Administrator entries</h1>\n<p>Edit the central time-entry record. Changes appear throughout MARS-IP. Linked <strong>draft</strong> invoice lines are synchronized; issued invoices remain unchanged for accounting history.</p>\n<section class="card">\n<form method="get" class="grid" id="entry-filter-v24">\n<label>Timekeeper<select name="user_id"><option value="">All</option>{% for u in users %}<option value="{{u.id}}" {% if selected_user==u.id %}selected{% endif %}>{{u.display_name}}</option>{% endfor %}</select></label>\n<label>Client<select name="client_id" id="entry-filter-client-v24"><option value="">All</option>{% for c in clients %}<option value="{{c.id}}" {% if selected_client==c.id %}selected{% endif %}>{{c.name}}</option>{% endfor %}</select></label>\n<label>Matter<select name="matter_id" id="entry-filter-matter-v24"><option value="">All</option>{% for m in matters %}<option value="{{m.id}}" data-client="{{m.client_id}}" {% if selected_matter==m.id %}selected{% endif %}>{{m.reference or \'\'}} | {{m.name}}</option>{% endfor %}</select></label>\n<label>From<input type="date" name="date_from" value="{{date_from}}"></label>\n<label>To<input type="date" name="date_to" value="{{date_to}}"></label>\n<label>Billing status<select name="billing"><option value="">All</option><option value="Unbilled" {% if billing==\'Unbilled\' %}selected{% endif %}>Unbilled</option><option value="Invoiced" {% if billing==\'Invoiced\' %}selected{% endif %}>Invoiced</option></select></label>\n<div><button>Apply filters</button> <a href="{{url_for(\'entries_v14\')}}">Clear</a></div>\n</form>\n</section>\n<section class="card"><strong>Displayed totals:</strong> Worked {{\'%.4f\'|format(total_worked)}} h | Billable {{\'%.4f\'|format(total_billable)}} h | Revenue {{\'%.2f\'|format(total_amount)}} EUR</section>\n<section class="card wide"><div class="table-scroll"><table class="admin-entry-edit-v24">\n<tr><th>Date</th><th>Timekeeper</th><th>Client</th><th>Matter</th><th>Service description / notes</th><th>Worked</th><th>Billable</th><th>Rate</th><th>Amount</th><th>Billable?</th><th>Invoice</th><th>Save</th></tr>\n{% for t in entries %}\n<tr>\n<td><form id="entry-v24-{{t.id}}" method="post" action="{{url_for(\'admin_entry_save_v24\',timer_id=t.id)}}"></form><input form="entry-v24-{{t.id}}" type="date" name="service_date" value="{{t.start_time.strftime(\'%Y-%m-%d\')}}" required></td>\n<td><select form="entry-v24-{{t.id}}" name="user_id" required>{% for u in users %}<option value="{{u.id}}" {% if u.id==t.user_id %}selected{% endif %}>{{u.display_name}}</option>{% endfor %}</select></td>\n<td><select form="entry-v24-{{t.id}}" name="client_id" class="entry-client-v24" data-row="{{t.id}}" required>{% for c in clients %}<option value="{{c.id}}" {% if c.id==t.client_id %}selected{% endif %}>{{c.name}}</option>{% endfor %}</select></td>\n<td><select form="entry-v24-{{t.id}}" name="matter_id" class="entry-matter-v24" data-row="{{t.id}}" required>{% for m in matters %}<option value="{{m.id}}" data-client="{{m.client_id}}" {% if m.id==t.matter_id %}selected{% endif %}>{{m.reference or \'\'}} | {{m.name}}</option>{% endfor %}</select></td>\n<td><textarea form="entry-v24-{{t.id}}" name="services" required>{{t.services}}</textarea><textarea form="entry-v24-{{t.id}}" name="notes" placeholder="Internal notes">{{t.notes or \'\'}}</textarea></td>\n<td><input form="entry-v24-{{t.id}}" type="number" min="0" step="0.0001" name="worked_hours" value="{{t.worked_hours or 0}}" required></td>\n<td><input form="entry-v24-{{t.id}}" type="number" min="0" step="0.0001" name="billable_hours" value="{{t.billable_hours or 0}}" required></td>\n<td><input form="entry-v24-{{t.id}}" type="number" min="0" step="0.01" name="applied_rate" value="{{t.applied_rate or 0}}" required></td>\n<td><input form="entry-v24-{{t.id}}" type="number" min="0" step="0.01" name="amount" value="{{t.amount or 0}}"><label class="check"><input form="entry-v24-{{t.id}}" type="checkbox" name="recalculate_amount" checked> Calculate hours × rate</label></td>\n<td><label class="check"><input form="entry-v24-{{t.id}}" type="checkbox" name="billable" {% if t.billable %}checked{% endif %}> Yes</label></td>\n<td>{{invoice_refs.get(t.id,\'\') or t.invoice_number or t.invoiced_status or \'Unbilled\'}}{% if issued_refs.get(t.id) %}<br><small>Issued invoice history preserved</small>{% endif %}</td>\n<td><button form="entry-v24-{{t.id}}">Save</button></td>\n</tr>\n{% else %}<tr><td colspan="12">No entries match the filters.</td></tr>{% endfor %}\n</table></div></section>\n<style>\n.admin-entry-edit-v24{min-width:1500px}.admin-entry-edit-v24 td{vertical-align:top}.admin-entry-edit-v24 textarea{min-width:260px;min-height:82px;display:block;margin-bottom:6px}.admin-entry-edit-v24 select,.admin-entry-edit-v24 input{max-width:220px}.admin-entry-edit-v24 input[type=number]{min-width:90px}.admin-entry-edit-v24 .check{font-size:12px;white-space:normal}.table-scroll{overflow-x:auto;max-width:100%}\n</style>\n<script>\n(function(){\n function filterMatter(clientSelect,matterSelect){\n  const cid=String(clientSelect.value), current=String(matterSelect.value); let visibleCurrent=false;\n  [...matterSelect.options].forEach(o=>{const show=!o.value||!cid||String(o.dataset.client)===cid;o.hidden=!show;o.disabled=!show;if(show&&String(o.value)===current)visibleCurrent=true;});\n  if(!visibleCurrent){const first=[...matterSelect.options].find(o=>!o.disabled&&o.value);if(first)matterSelect.value=first.value;}\n }\n const fc=document.getElementById(\'entry-filter-client-v24\'),fm=document.getElementById(\'entry-filter-matter-v24\');if(fc&&fm){filterMatter(fc,fm);fc.addEventListener(\'change\',()=>filterMatter(fc,fm));}\n document.querySelectorAll(\'.entry-client-v24\').forEach(c=>{const m=document.querySelector(\'.entry-matter-v24[data-row="\'+c.dataset.row+\'"]\');if(m){filterMatter(c,m);c.addEventListener(\'change\',()=>filterMatter(c,m));}});\n document.querySelectorAll(\'form[id^="entry-v24-"]\').forEach(f=>{const row=f.closest(\'tr\')||document;const bh=row.querySelector(\'[name=billable_hours]\'),rate=row.querySelector(\'[name=applied_rate]\'),amount=row.querySelector(\'[name=amount]\'),calc=row.querySelector(\'[name=recalculate_amount]\');function update(){if(calc&&calc.checked&&bh&&rate&&amount)amount.value=((parseFloat(bh.value)||0)*(parseFloat(rate.value)||0)).toFixed(2)};[bh,rate,calc].forEach(x=>x&&x.addEventListener(\'input\',update));});\n})();\n</script>\n{% endblock %}\'\'\'\n\n\ndef admin_entries_editable_v24():\n    selected_user=request.args.get(\'user_id\',type=int)\n    selected_client=request.args.get(\'client_id\',type=int)\n    selected_matter=request.args.get(\'matter_id\',type=int)\n    date_from=(request.args.get(\'date_from\') or \'\').strip()\n    date_to=(request.args.get(\'date_to\') or \'\').strip()\n    billing=(request.args.get(\'billing\') or \'\').strip()\n    query=Timer.query\n    if selected_user: query=query.filter(Timer.user_id==selected_user)\n    if selected_client: query=query.filter(Timer.client_id==selected_client)\n    if selected_matter: query=query.filter(Timer.matter_id==selected_matter)\n    if billing: query=query.filter(Timer.invoiced_status==billing)\n    try:\n        if date_from:\n            start=datetime.strptime(date_from,\'%Y-%m-%d\').replace(tzinfo=timezone.utc);query=query.filter(Timer.start_time>=start)\n        if date_to:\n            end=datetime.strptime(date_to,\'%Y-%m-%d\').replace(tzinfo=timezone.utc)+timedelta(days=1);query=query.filter(Timer.start_time<end)\n    except ValueError:\n        flash(\'Use valid From and To dates.\')\n    entries=query.order_by(Timer.start_time.desc(),Timer.id.desc()).all()\n    refs={t.id:invoice_references_text_v15(t.id) for t in entries}\n    issued={t.id:[x.invoice_number for x in TimerInvoiceLinkV18.query.filter_by(timer_id=t.id).all()] for t in entries}\n    return render_template_string(ADMIN_ENTRIES_V24,entries=entries,users=User.query.order_by(User.display_name).all(),clients=Client.query.order_by(Client.name).all(),matters=Matter.query.order_by(Matter.name).all(),selected_user=selected_user,selected_client=selected_client,selected_matter=selected_matter,date_from=date_from,date_to=date_to,billing=billing,invoice_refs=refs,issued_refs=issued,total_worked=sum(_v24_float(t.worked_hours) for t in entries),total_billable=sum(_v24_float(t.billable_hours) for t in entries),total_amount=sum(_v24_float(t.amount) for t in entries))\n\n\n@app.post(\'/admin/entries-v24/<int:timer_id>/save\')\n@login_required\n@admin_required\ndef admin_entry_save_v24(timer_id):\n    t=db.session.get(Timer,timer_id)\n    if not t:return (\'Not found\',404)\n    before=_v24_entry_snapshot(t)\n    user=db.session.get(User,request.form.get(\'user_id\',type=int))\n    client=db.session.get(Client,request.form.get(\'client_id\',type=int))\n    matter=db.session.get(Matter,request.form.get(\'matter_id\',type=int))\n    if not user or not client or not matter or matter.client_id!=client.id:\n        flash(\'Invalid timekeeper, client, or matter selection.\')\n        return redirect(request.referrer or url_for(\'entries_v14\'))\n    try:\n        service_date=datetime.strptime(request.form[\'service_date\'],\'%Y-%m-%d\').date()\n        old_time=t.start_time.timetz() if t.start_time else datetime.min.time()\n        t.start_time=datetime.combine(service_date,old_time)\n        if t.start_time.tzinfo is None:t.start_time=t.start_time.replace(tzinfo=timezone.utc)\n        t.user_id=user.id;t.client_id=client.id;t.matter_id=matter.id\n        t.services=(request.form.get(\'services\') or \'\').strip();t.notes=(request.form.get(\'notes\') or \'\').strip()\n        t.worked_hours=max(0,_v24_float(request.form.get(\'worked_hours\')))\n        t.billable=(\'billable\' in request.form)\n        t.billable_hours=max(0,_v24_float(request.form.get(\'billable_hours\'))) if t.billable else 0\n        t.applied_rate=max(0,_v24_float(request.form.get(\'applied_rate\')))\n        t.amount=_v18_money(t.billable_hours*t.applied_rate) if \'recalculate_amount\' in request.form else _v18_money(max(0,_v24_float(request.form.get(\'amount\'))))\n        # Keep rate-source snapshots internally coherent with the chosen master records.\n        t.timekeeper_rate=user.default_hourly_rate;t.client_rate=client.client_hourly_rate;t.matter_rate=matter.matter_hourly_rate\n        # Synchronize only draft invoice lines. Issued invoice lines remain historical.\n        for line in FeeNoteLine.query.filter_by(source_timer_id=t.id).all():\n            draft=db.session.get(FeeNoteDraft,line.draft_id)\n            if draft and (draft.status or \'Draft\')==\'Draft\':\n                line.description=t.services;line.service_date=service_date.isoformat();line.timekeeper=user.display_name;line.quantity=t.billable_hours;line.rate=t.applied_rate;line.amount=t.amount\n                if not line.amount_override:line.amount=_v18_money(line.quantity*line.rate)\n                recalculate(draft)\n        _v18_log(\'timer\',t.id,\'admin_full_edit\',before,_v24_entry_snapshot(t))\n        db.session.commit();flash(\'Entry updated in the central database. Draft invoice lines were synchronized; issued invoices were preserved.\')\n    except Exception as exc:\n        db.session.rollback();flash(\'Entry was not saved: \'+str(exc))\n    return redirect(request.referrer or url_for(\'entries_v14\'))\n\n\n# Preserve the existing /entries-v14 URL while replacing its view with the full editor.\napp.view_functions[\'entries_v14\']=login_required(admin_required(admin_entries_editable_v24))\n'
shutil.copy2(p,backup)
p.write_text(s.rstrip()+patch+"\n",encoding="utf-8")
try: py_compile.compile(str(p),doraise=True)
except Exception:
 shutil.copy2(backup,p);raise
print("Admin Entries V24 installed.")
print("Rollback:",backup)
print("Syntax validation passed.")
